import pathlib,sqlite3,json,hashlib,datetime,uuid
P=pathlib.Path(__file__).resolve().parent
D=P/('route-readonly-'+uuid.uuid4().hex);D.mkdir()
db=P/'case-02-0-none-evidence/case.sqlite'
def ref(f):return {'path':str(f),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'bytes':f.stat().st_size}
def write(n,v):
 with (D/n).open('x',encoding='utf-8') as w:json.dump(v,w,ensure_ascii=False,indent=2);w.write('\n')
before=ref(db)
if before['sha256']!='c6878f2f09811deabc93712dc51b0f05148c311d959cbe02ebb07e9db15d76da':raise SystemExit('diagnosis copy drift')
q1='SELECT project,run,effect_key,sequence,body FROM resource_effects ORDER BY project,run,effect_key,sequence'
q2='SELECT project,run,epoch,dispatch_key,manifest,manifest_hash FROM runtime_dispatches ORDER BY project,run,epoch'
write('invocation.json',{'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'script':ref(pathlib.Path(__file__)),'db':before,'sqlite_uri_mode':'ro&immutable=1','queries':[q1,q2],'product_cases':0,'model_calls':0,'worker_starts':0,'HTTP':0,'reason':'Root requested read-only exact original route/key evidence after stop; no validator invoked'})
conn=sqlite3.connect(db.as_uri()+'?mode=ro&immutable=1',uri=True)
effects=[]
for project,run,key,seq,raw in conn.execute(q1):
 v=json.loads(raw);req=v.get('payload',{})
 effects.append({'project':project,'run':run,'effect_key':key,'sequence':seq,'task_id':v.get('task_id'),'epoch':v.get('epoch'),'state':v.get('state'),'capability':req.get('capability'),'route':req.get('route'),'credential_revision':req.get('credential_revision'),'provider_transport_present':'provider_transport' in req,'request_hash':v.get('request_hash'),'reservation_id':v.get('reservation_id'),'full_effect_body_sha256':hashlib.sha256(raw.encode()).hexdigest()})
dispatches=[]
for project,run,epoch,key,raw,digest in conn.execute(q2):
 m=json.loads(raw);a=m.get('admission',{});p=a.get('profile',{})
 dispatches.append({'project':project,'run':run,'epoch':epoch,'dispatch_key':key,'manifest_hash':digest,'task_id':m.get('task_id'),'runtime_id':m.get('runtime_id'),'profile_ref':a.get('profile_ref'),'runtime_ref':a.get('runtime_ref'),'profile_hash':a.get('profile_hash'),'effect_routes':p.get('effect_routes'),'model_route':p.get('model_config',{}).get('route'),'provider_policy':p.get('model_config',{}).get('provider_policy')})
conn.close()
after=ref(db)
if before!=after:raise SystemExit('read-only diagnosis drift')
write('facts.json',{'effects':effects,'dispatches':dispatches,'db_before':before,'db_after':after,'unchanged':True,'product_cases':0,'status':'READONLY_HISTORICAL_FACTS_NOT_VALIDATOR_REPLAY'})
write('scope_proposal.json',{'status':'EXACT2_CAUSAL_SCOPE_PROPOSED_NOT_AUTHORIZED','issue':'P9-P12-SR01','issue_failed_invocations_after':3,'author_attempts_so_far':2,'old_history_refusals':5,'facts':ref(D/'facts.json'),'prior_stopped_manifest':ref(P/'stopped_manifest.json'),'positive_progress':['Untouched PREPARED: both validators accept and inventory_count=1.','Original P12 red: both reject at the required missing original dispatch/provenance boundary.'],'remaining_failure':'Unchanged sameRun original TOOL receipt is classified MODEL because profile MODEL route shares its route id. Whole attempt remains failed; 47 planned cases not run.','exact_paths':[{'path':'internal/domain/runtime_model_verification.go','bounds':'Only original effect classification in validateProviderInventory and narrowly related canonical route/request proof helper. Preserve typed epoch fix and sealed Run/admission/profile joins. No change wire/system/history/SDK/transport/affinity or public schemas.'},{'path':'internal/domain/runtime_provider_binding_windows_test.go','bounds':'Zero-model original shared-route baseline plus typed route/key/request corruption controls, all current correct-cause assertions retained. Never execute held native positives.'}],'recommended_guard':['Treat the existing canonical provider route as typed identity: route id, capability, credential_revision, and upper_bound. ID alone is not proof of MODEL.','Retain independent original MODEL hints: canonical SQL key prefix/ordinal, request MODEL capability, original provider_transport, plus frozen MODEL credential/route tuple where unambiguous. Changed key+capability must still be caught by tuple and original request/reservation proof.','To exclude a positively identified non-MODEL effect on an original native policy Run, require exactly one full original non-MODEL route match and validate original canonical key/epoch/project/task/request_hash against its immutable reservation and bound money. A claimed TOOL or deleted marker alone must not bypass original MODEL obligation.','If MODEL and TOOL tuple evidence collides or binding/proof is absent, reject ambiguity/provenance; do not use current profile/head, fixture flag or policy marker as a whitelist.','Preserve original MODEL PREPARED/state sequence checks, sealed admission joins, missing dispatch/double-marker rejection and UNKNOWN money remains reserved. No repair of historical facts.'],'required_controls':['Unmodified original sameRun archive must contain its original MODEL and TOOL keys/routes and pass both validators; this does not requalify held model history.','Unchanged PREPARED and original exact P12 red correct-cause controls remain prerequisites.','Copied original MODEL capability/key/credential mutations cannot become legitimate TOOL; original request_hash and reservation bound tampering reject.','Explicit synthetic shared-route and ambiguous typed tuple controls must be labelled SYNTHETIC_NOT_PRODUCT.','All original closed states/doublemarker controls only after prerequisites pass; first unexpected result stops without another automatic source change.'],'scope_decision_pending':'Root and non-author cause review must decide the exact typed non-MODEL proof rule and any added authorized case budget before implementation. This document executes no correction or case.','models':0,'workers':0,'HTTP':0,'canonical_edits':0})
write('manifest.json',{'files':[ref(f) for f in sorted(D.iterdir()) if f.is_file()],'self_excluded':True})
print(json.dumps({n:ref(D/n) for n in ['facts.json','scope_proposal.json','manifest.json']},ensure_ascii=True,indent=2))
